2.34.1

The code statements that lead to the bug are:

```c
static int riic_i2c_suspend(struct device *dev)
{
    ...
    i2c_mark_adapter_suspended(&riic->adapter);
    riic_clear_set_bit(riic, ICCR1_ICE, 0, RIIC_ICCR1);
    pm_runtime_mark_last_busy(dev);
    pm_runtime_put_sync(dev);
    return reset_control_assert(riic->rstc);
}
```

```c
static int riic_i2c_resume(struct device *dev)
{
    ...
    ret = reset_control_deassert(riic->rstc);
    ...
    ret = riic_init_hw(riic);
    ...
    i2c_mark_adapter_resumed(&riic->adapter);
}
```

Reason:
The original suspend/resume callbacks performed hardware operations (disabling the controller, asserting reset, reinitializing) in the normal system sleep phase (`suspend()` and `resume()`). This caused the I2C controller to become unavailable before the noirq phase, where other devices (e.g., RTC) may still attempt I2C transfers, triggering the "Transfer while suspended" warning.

The code statements that fix the bug are:

```c
static int riic_i2c_suspend(struct device *dev)
{
    return pm_runtime_resume_and_get(dev);
}

static int riic_i2c_resume(struct device *dev)
{
    pm_runtime_put_autosuspend(dev);
    return 0;
}

static int riic_i2c_suspend_noirq(struct device *dev)
{
    struct riic_dev *riic = dev_get_drvdata(dev);
    i2c_mark_adapter_suspended(&riic->adapter);
    riic_clear_set_bit(riic, ICCR1_ICE, 0, RIIC_ICCR1);
    pm_runtime_mark_last_busy(dev);
    pm_runtime_force_suspend(dev);
    return reset_control_assert(riic->rstc);
}

static int riic_i2c_resume_noirq(struct device *dev)
{
    struct riic_dev *riic = dev_get_drvdata(dev);
    int ret;
    ret = reset_control_deassert(riic->rstc);
    if (ret) return ret;
    ret = pm_runtime_force_resume(dev);
    if (ret) return ret;
    ret = riic_init_hw(riic);
    if (ret) { reset_control_assert(riic->rstc); return ret; }
    i2c_mark_adapter_resumed(&riic->adapter);
    return 0;
}
```

Reason:
The fix moves the actual hardware suspend/resume operations (disable controller, assert/deassert reset, reinit hardware, mark adapter suspended/resumed) to the `suspend_noirq()` and `resume_noirq()` callbacks. The normal `suspend()` callback now only wakes up the controller (via `pm_runtime_resume_and_get()`), ensuring it remains active through the noirq phase. The normal `resume()` callback re-enables autosuspend (via `pm_runtime_put_autosuspend()`). This ensures the I2C controller is available during the noirq phase when other devices may need it, and the hardware state transitions occur at the correct time.

